import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // A: (M, K)
    // B: (N, K) but we want B^T (K, N), so each element B^T(i, j) = B(j, i).
    // C: (M, N) = A * B^T

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float val = 0.0f;
        for (int i = 0; i < K; i++) {
            val += A[row * K + i] * B[col * K + i];
        }
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // A: (M, K), B: (N, K)
    // C: (M, N)
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");

    int64_t M = A.size(0);
    int64_t K = A.size(1);
    TORCH_CHECK(B.size(1) == K, "B must have shape (N, K) so that K matches A's second dimension");
    int64_t N = B.size(0);

    auto C = torch::zeros({M, N}, A.options());

    dim3 block(16, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N
    );
    return C;
}
"""

matmul_cpp_source = r"""
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

matmul_extension = load_inline(
    name="matmul_extension",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul_func = matmul_extension

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Original operation: torch.matmul(A, B.T)
        # We handle the B.T in the custom kernel directly.
        return self.matmul_func.matmul_cuda(A, B.cuda())
